fn frame(t: i32) {
    host::display::clear(0x0e0f12);
    let palette = [0x14161c, 0xffcc33, 0x33ff88, 0x66aaff];
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(21);
    host::display::state_set(21, down);
    let sel: i32 = host::display::state_get(20);

    if down == 1 && px >= 96 && px < 416 && py >= 40 && py < 360 {
        let cx: i32 = (px - 96) / 40;
        let cy: i32 = (py - 40) / 40;
        let row: i32 = host::display::state_get(10 + cy);
        let cur: i32 = (row >> (cx * 2)) & 3;
        host::display::state_set(10 + cy, row - (cur << (cx * 2)) + (sel << (cx * 2)));
    }

    if down == 1 && prev == 0 {
        if py >= 380 && py < 420 && px >= 96 && px < 376 {
            let pick: i32 = (px - 96) / 70;
            if pick >= 0 && pick < 4 {
                host::display::state_set(20, pick);
            }
        }
        if py >= 440 && py < 480 {
            if px >= 96 && px < 186 {
                let mut i: i32 = 0;
                while i < 8 {
                    host::display::state_set(30 + i, host::display::state_get(10 + i));
                    i = i + 1;
                }
                host::display::state_set(22, 30);
            }
            if px >= 206 && px < 296 {
                let mut j: i32 = 0;
                while j < 8 {
                    host::display::state_set(10 + j, host::display::state_get(30 + j));
                    j = j + 1;
                }
            }
            if px >= 316 && px < 416 {
                let mut k: i32 = 0;
                while k < 8 {
                    host::display::state_set(10 + k, 0);
                    k = k + 1;
                }
            }
        }
    }

    let mut cy2: i32 = 0;
    while cy2 < 8 {
        let row2: i32 = host::display::state_get(10 + cy2);
        let mut cx2: i32 = 0;
        while cx2 < 8 {
            host::display::fill_rect(96 + cx2 * 40 + 1, 40 + cy2 * 40 + 1, 38, 38, palette[(row2 >> (cx2 * 2)) & 3]);
            cx2 = cx2 + 1;
        }
        cy2 = cy2 + 1;
    }

    let mut s: i32 = 0;
    while s < 4 {
        if s == sel {
            host::display::fill_rect(94 + s * 70, 378, 64, 44, 0xffffff);
        }
        host::display::fill_rect(96 + s * 70, 380, 60, 40, palette[s]);
        s = s + 1;
    }
    host::display::fill_rect(96, 440, 90, 40, 0x232833);
    host::display::draw_string(112, 452, "SAVE", 0xffffff, 1);
    host::display::fill_rect(206, 440, 90, 40, 0x232833);
    host::display::draw_string(222, 452, "LOAD", 0xffffff, 1);
    host::display::fill_rect(316, 440, 100, 40, 0x232833);
    host::display::draw_string(332, 452, "CLEAR", 0xffffff, 1);
    let flash: i32 = host::display::state_get(22);
    if flash > 0 {
        host::display::draw_string(96, 14, "SAVED TO THE SLOT", 0x33ff88, 1);
        host::display::state_set(22, flash - 1);
    } else {
        host::display::draw_string(96, 14, "DRAG TO PAINT", 0x556677, 1);
    }
    host::display::present();
}
